    public DateTime ShippedDate { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Exception
}

namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<Shipment> CreateShipmentAsync(Shipment shipment);
    Task<Shipment> UpdateShipmentStatusAsync(int id, ShipmentStatus status);
}

namespace ShipmentTracker.Client.Services;

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

public class ShipmentServiceClient(HttpClient httpClient) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await httpClient.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var response = await httpClient.GetAsync($"api/shipments/track/{trackingNumber}");
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<Shipment>();
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        var response = await httpClient.PostAsJsonAsync("api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<Shipment>())!;
    }

    public async Task<Shipment> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var response = await httpClient.PutAsJsonAsync($"api/shipments/{id}/status", status);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<Shipment>())!;
    }
}

namespace ShipmentTracker.Data;

using ShipmentTracker.Client.Models;

public class ShipmentEntity
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace ShipmentTracker.Services;

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

public class ShipmentServiceServer(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .Select(e => MapToModel(e))
            .ToListAsync();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var entity = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return entity is null ? null : MapToModel(entity);
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        var entity = new ShipmentEntity
        {
            TrackingNumber = shipment.TrackingNumber,
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            Status = shipment.Status,
            ShippedDate = shipment.ShippedDate,
            EstimatedDelivery = shipment.EstimatedDelivery,
            CustomerEmail = shipment.CustomerEmail,
            Description = shipment.Description
        };

        db.Shipments.Add(entity);
        await db.SaveChangesAsync();
        return MapToModel(entity);
    }

    public async Task<Shipment> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var entity = await db.Shipments.FindAsync(id)
            ?? throw new InvalidOperationException($"Shipment {id} not found.");
        entity.Status = status;
        if (status == ShipmentStatus.Delivered)
            entity.ActualDelivery = DateTime.UtcNow;
        await db.SaveChangesAsync();
        return MapToModel(entity);
    }

    private static Shipment MapToModel(ShipmentEntity e) => new()
    {
        Id = e.Id,
        TrackingNumber = e.TrackingNumber,
        Origin = e.Origin,
        Destination = e.Destination,
        Status = e.Status,
        ShippedDate = e.ShippedDate,
        EstimatedDelivery = e.EstimatedDelivery,
        ActualDelivery = e.ActualDelivery,
        CustomerEmail = e.CustomerEmail,
        Description = e.Description
    };
}

namespace ShipmentTracker;

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("", async (IShipmentService service) =>
            Results.Ok(await service.GetAllShipmentsAsync()));

        group.MapGet("track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        }).AllowAnonymous();

        group.MapPost("", async (Shipment shipment, IShipmentService service) =>
        {
            var created = await service.CreateShipmentAsync(shipment);
            return Results.Created($"api/shipments/track/{created.TrackingNumber}", created);
        });

        group.MapPut("{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
        {
            var updated = await service.UpdateShipmentStatusAsync(id, status);
            return Results.Ok(updated);
        });

        if (app.Environment.IsDevelopment())
        {
            app.MapPost("api/shipments/seed", async (IShipmentService service) =>
            {
                var samples = new[]
                {
                    new Shipment { Origin = "New York, USA", Destination = "London, UK", CustomerEmail = "customer1@example.com", Description = "Electronics Package", TrackingNumber = $"ST-{Guid.NewGuid().ToString()[..8].ToUpper()}", ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(4), Status = ShipmentStatus.InTransit },
                    new Shipment { Origin = "Tokyo, Japan", Destination = "Sydney, Australia", CustomerEmail = "customer2@example.com", Description = "Auto Parts", TrackingNumber = $"ST-{Guid.NewGuid().ToString()[..8].ToUpper()}", ShippedDate = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(6), Status = ShipmentStatus.PickedUp },
                    new Shipment { Origin = "Berlin, Germany", Destination = "Paris, France", CustomerEmail = "customer3@example.com", Description = "Medical Supplies", TrackingNumber = $"ST-{Guid.NewGuid().ToString()[..8].ToUpper()}", ShippedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow.AddDays(-1), Status = ShipmentStatus.Delivered, ActualDelivery = DateTime.UtcNow.AddDays(-1) },
                    new Shipment { Origin = "São Paulo, Brazil", Destination = "Mexico City, Mexico", CustomerEmail = "customer4@example.com", Description = "Textiles", TrackingNumber = $"ST-{Guid.NewGuid().ToString()[..8].ToUpper()}", ShippedDate = DateTime.UtcNow.AddDays(-2), EstimatedDelivery = DateTime.UtcNow.AddDays(3), Status = ShipmentStatus.OutForDelivery },
                };
                foreach (var s in samples) await service.CreateShipmentAsync(s);
                return Results.Ok("Seeded 4 sample shipments.");
            }).AllowAnonymous();
        }
    }
}

